import React from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import { Box, Typography, Paper, Card, CardContent, CircularProgress, Alert } from '@mui/material';

const OrgChartPage = () => {
  const { t } = useTranslation();
  const { data, isLoading, error } = useQuery({
    queryKey: ['orgchart-tree'],
    queryFn: () => axiosInstance.get('/org-chart/positions/tree/').then(r => r.data),
  });

  const renderNode = (node, depth = 0) => (
    <Card key={node.id} variant="outlined" sx={{ ml: depth * 3, mb: 1, borderLeft: `4px solid ${['#1976d2', '#ed6c02', '#2e7d32'][depth % 3]}` }}>
      <CardContent sx={{ py: 1 }}>
        <Typography variant="subtitle2" fontWeight="bold">{node.title}</Typography>
        <Typography variant="caption" color="textSecondary">{node.department_name || ''} (سطح {node.level})</Typography>
        {node.employees?.length > 0 && (
          <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
            پرسنل: {node.employees.map(e => e.full_name).join('، ')}
          </Typography>
        )}
      </CardContent>
      {node.children?.map(child => renderNode(child, depth + 1))}
    </Card>
  );

  return (
    <Box>
      <Typography variant="h4" gutterBottom>{t('orgchart.title')}</Typography>
      <Paper sx={{ p: 3 }}>
        {isLoading ? <CircularProgress /> : error ? <Alert severity="error">{error.message}</Alert> : (
          data?.map(node => renderNode(node))
        )}
        {data?.length === 0 && <Typography color="textSecondary">{t('common.noData')}</Typography>}
      </Paper>
    </Box>
  );
};

export default OrgChartPage;
